fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    let max_len = m.max(n);

    // Both have same length: return copies of inputs
    if m == n {
        (a.clone(), b.clone())
    }
    // a has length 1, b longer: repeat a[0], copy b as is
    else if m == 1 {
        (vec![a[0]; max_len], b.clone())
    }
    // b has length 1, a longer: copy a as is, repeat b[0]
    else if n == 1 {
        (a.clone(), vec![b[0]; max_len])
    }
    // According to problem statement inputs are guaranteed compatible,
    // so no other cases are possible.
    else {
        unreachable!("Inputs are not compatible lengths")
    }
}